package authbridge

import (
	"crypto/hmac"
	"crypto/rand"
	"crypto/sha256"
	"encoding/hex"
	"fmt"
	"sync"
	"time"
)

// TokenGrant represents a cross-service authentication grant
type TokenGrant struct {
	ServiceID   string
	Permissions []string
	IssuedAt    int64
	ExpiresAt   int64
	Nonce       string
	Delegated   bool
}

// GrantLedger tracks active grants to prevent replay
type GrantLedger struct {
	mu      sync.RWMutex
	active  map[string]*TokenGrant
	revoked map[string]bool
	secret  []byte
}

func NewGrantLedger(secret []byte) *GrantLedger {
	return &GrantLedger{
		active:  make(map[string]*TokenGrant),
		revoked: make(map[string]bool),
		secret:  secret,
	}
}

// generateNonce produces a cryptographically secure random nonce
func generateNonce() (string, error) {
	b := make([]byte, 16)
	if _, err := rand.Read(b); err != nil {
		return "", err
	}
	return hex.EncodeToString(b), nil
}

// computeGrantID derives a unique identifier for the grant
func (gl *GrantLedger) computeGrantID(grant *TokenGrant) string {
	mac := hmac.New(sha256.New, gl.secret)
	mac.Write([]byte(fmt.Sprintf("%s:%s:%d:%s",
		grant.ServiceID, grant.Permissions, grant.IssuedAt, grant.Nonce)))
	return hex.EncodeToString(mac.Sum(nil))
}

// IssueGrant creates a new cross-service authentication grant
func (gl *GrantLedger) IssueGrant(serviceID string, permissions []string, ttlSeconds int64) (*TokenGrant, string, error) {
	now := time.Now().Unix()
	nonce, err := generateNonce()
	if err != nil {
		return nil, "", fmt.Errorf("failed to generate nonce: %w", err)
	}
	grant := &TokenGrant{
		ServiceID:   serviceID,
		Permissions: permissions,
		IssuedAt:    now,
		ExpiresAt:   now + ttlSeconds,
		Nonce:       nonce,
		Delegated:   false,
	}

	grantID := gl.computeGrantID(grant)

	gl.mu.Lock()
	gl.active[grantID] = grant
	gl.mu.Unlock()

	return grant, grantID, nil
}

// DelegateGrant allows a service to delegate its grant to another service
// This implements a "flash" delegation pattern where the grant is temporarily
// extended to a delegate, then revoked from the original holder
func (gl *GrantLedger) DelegateGrant(originalGrantID string, targetServiceID string) (*TokenGrant, string, error) {
	gl.mu.Lock()
	defer gl.mu.Unlock()

	original, exists := gl.active[originalGrantID]
	if !exists {
		return nil, "", fmt.Errorf("grant not found: %s", originalGrantID)
	}

	if gl.revoked[originalGrantID] {
		return nil, "", fmt.Errorf("grant has been revoked")
	}

	now := time.Now().Unix()
	if original.ExpiresAt < now {
		return nil, "", fmt.Errorf("grant has expired")
	}

	nonce, err := generateNonce()
	if err != nil {
		return nil, "", fmt.Errorf("failed to generate nonce: %w", err)
	}

	// Create delegated grant with same permissions
	delegated := &TokenGrant{
		ServiceID:   targetServiceID,
		Permissions: original.Permissions,
		IssuedAt:    now,
		ExpiresAt:   original.ExpiresAt,
		Nonce:       nonce,
		Delegated:   true,
	}

	delegatedID := gl.computeGrantID(delegated)

	// Atomically: revoke original, then register delegated grant
	gl.revoked[originalGrantID] = true
	gl.active[delegatedID] = delegated

	return delegated, delegatedID, nil
}

// ValidateGrant checks if a grant is currently valid and active
func (gl *GrantLedger) ValidateGrant(grantID string) (bool, *TokenGrant) {
	gl.mu.RLock()
	defer gl.mu.RUnlock()

	grant, exists := gl.active[grantID]
	if !exists {
		return false, nil
	}

	if gl.revoked[grantID] {
		return false, nil
	}

	now := time.Now().Unix()
	if grant.ExpiresAt < now {
		return false, nil
	}

	return true, grant
}

// ConsumeGrant atomically validates and consumes a grant for a one-time action
func (gl *GrantLedger) ConsumeGrant(grantID string, requiredPermission string) error {
	gl.mu.Lock()
	defer gl.mu.Unlock()

	grant, exists := gl.active[grantID]
	if !exists {
		return fmt.Errorf("invalid or expired grant")
	}

	if gl.revoked[grantID] {
		return fmt.Errorf("invalid or expired grant")
	}

	now := time.Now().Unix()
	if grant.ExpiresAt < now {
		return fmt.Errorf("invalid or expired grant")
	}

	hasPermission := false
	for _, p := range grant.Permissions {
		if p == requiredPermission {
			hasPermission = true
			break
		}
	}

	if !hasPermission {
		return fmt.Errorf("insufficient permissions")
	}

	// Mark as consumed (revoked after use)
	gl.revoked[grantID] = true

	return nil
}
